-- scanner fences: completion is compare-and-set fenced and cannot mark clean before scanner proof.
do $$declare allowed boolean:=true;begin begin update public.booking_attachments set upload_state='clean' where id='8a000000-0000-0000-0000-000000000001';exception when raise_exception then allowed:=false;end;if allowed then raise exception 'direct clean attachment mutation accepted';end if;end$$;
do $$declare allowed boolean:=true;begin begin perform public.mark_booking_attachment_uploaded('8a000000-0000-0000-0000-000000000001','81000000-0000-0000-0000-000000000001','test','test/81000000-0000-0000-0000-000000000001/82000000-0000-0000-0000-000000000001/87000000-0000-0000-0000-000000000010/8a000000-0000-0000-0000-000000000001',1,'sum-uploaded');exception when raise_exception then allowed:=false;end;if allowed then raise exception 'unproven upload object accepted';end if;end$$;
select pg_temp.assert_true((select upload_state='pending' from public.booking_attachments where id='8a000000-0000-0000-0000-000000000001'),'scanner remains fail closed without provider proof');

-- Weekly and override intervals reject overnight/zero-length ranges; custom overrides remain representable.
do $$declare allowed boolean:=true;begin begin perform public.save_shared_booking_availability('82000000-0000-0000-0000-000000000001','81000000-0000-0000-0000-000000000001','test','81000000-0000-0000-0000-000000000001',null,null,'{}','{}','[]',null);exception when invalid_parameter_value then allowed:=false;end;if allowed then raise exception 'null overrides accepted';end if;end$$;
insert into public.availability_overrides(id,schedule_id,profile_id,environment,local_date,override_type) values('8b000000-0000-0000-0000-000000000001','85000000-0000-0000-0000-000000000002','81000000-0000-0000-0000-000000000001','test',current_date+10,'custom_hours');
insert into public.availability_override_intervals(override_id,profile_id,environment,local_start,local_end,sort_order) values('8b000000-0000-0000-0000-000000000001','81000000-0000-0000-0000-000000000001','test','09:00','12:00',0);
select pg_temp.assert_true((select count(*)=1 from public.availability_override_intervals where override_id='8b000000-0000-0000-0000-000000000001'),'custom overrides');
do $$declare allowed boolean:=true;begin begin insert into public.availability_override_intervals(override_id,profile_id,environment,local_start,local_end,sort_order) values('8b000000-0000-0000-0000-000000000001','81000000-0000-0000-0000-000000000001','test','22:00','02:00',1);exception when check_violation then allowed:=false;end;if allowed then raise exception 'overnight rejection missing';end if;end$$;

-- Governance preserves records on offboarding, and every purge/audit actor is attributable.
select public.offboard_starter_leads('81000000-0000-0000-0000-000000000002','81000000-0000-0000-0000-000000000002','contract ended');
select pg_temp.assert_true((select count(*)=1 from public.leads where id=(select id from submitted_lead)) and (select quote_admission=false from public.website_entitlements where id='84000000-0000-0000-0000-000000000002'),'offboarding retention');
select pg_temp.assert_true((select actor_user_id is not null and reason='contract ended' from public.lead_governance_events where profile_id='81000000-0000-0000-0000-000000000002' and action='offboard'),'purge attribution');
select pg_temp.assert_true((select snapshot_status='captured' and snapshot_version=1 from public.leads where id=(select id from submitted_lead)),'legacy snapshots');

-- Catalog checks complement TypeScript compile-time assertions without pretending to run TS in PostgreSQL.
select pg_temp.assert_true((select count(*)=4 from pg_catalog.pg_proc p join pg_catalog.pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in('ingest_provider_event','apply_saas_provider_event','complete_outbox_appointment_command','record_lead_governance_event')),'type fidelity');
select pg_temp.assert_true((select count(*)=2 from information_schema.columns where table_schema='public' and table_name='leads' and column_name in('snapshot_status','snapshot_version')),'type fidelity closure columns');
select pg_temp.assert_true((select count(*)=3 from information_schema.columns where table_schema='public' and ((table_name='calendar_connections' and column_name='last_verified_at') or (table_name='stripe_connected_accounts' and column_name='last_verified_at') or (table_name='pipedream_bindings' and column_name='last_health_at'))),'provider freshness/shared readiness');
select pg_temp.assert_true(not has_table_privilege('service_role','public.booking_attachments','INSERT,UPDATE,DELETE,TRUNCATE'),'attachment direct service DML revoked');
select pg_temp.assert_true(not has_table_privilege('service_role','public.lead_governance_events','INSERT,UPDATE,DELETE,TRUNCATE'),'governance direct service DML revoked');
select pg_temp.assert_true(not has_function_privilege('service_role','public.apply_provider_appointment_event(uuid,uuid,bigint,uuid,uuid,text,bigint,text,uuid,text,jsonb)','EXECUTE'),'generic provider adapter execute revoked');

rollback;
